/**
 * 获取指定省份的所有多分支生态剧本
 */
export function getEcosystemsByProvince(targetProvince: string): RegionEcosystem[] {
  const clean = targetProvince.trim();
  return REGION_ECOSYSTEMS.filter(
    (e) =>
      e.province === clean ||
      e.id === clean ||
      clean.includes(e.province) ||
      e.province.includes(clean)
  );
}
